import{_ as t,o as i,c as n,a5 as a}from"./chunks/framework.CsGesDJn.js";const w=JSON.parse('{"title":"Sequence Flow — View Agency Invitation Status","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-8-view-agency-invitation-status/sequence-flow.md","filePath":"feature/agency-workspace/3-4-8-view-agency-invitation-status/sequence-flow.md"}'),o={name:"feature/agency-workspace/3-4-8-view-agency-invitation-status/sequence-flow.md"};function s(l,e,r,d,c,h){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="sequence-flow-—-view-agency-invitation-status" tabindex="-1">Sequence Flow — View Agency Invitation Status <a class="header-anchor" href="#sequence-flow-—-view-agency-invitation-status" aria-label="Permalink to &quot;Sequence Flow — View Agency Invitation Status&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.8). This file lists each actor → action → system step in enough detail to draw the sequence diagram directly. Business explanation lives in <code>spec.md</code>. &gt; &gt; Updated 2026-09-23, matching the system as built today.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Owner</strong> — owns the Agency.</li><li><strong>Invitee</strong> — the person invited.</li><li><strong>Client</strong> — the BrandHub web application.</li><li><strong>System</strong> — the BrandHub service.</li><li><strong>Database</strong> — PostgreSQL (<code>agency_invitations</code>).</li></ul><hr><h2 id="flow-a-—-the-owner-views-every-invitation-of-the-agency" tabindex="-1">Flow A — The Owner views every invitation of the Agency <a class="header-anchor" href="#flow-a-—-the-owner-views-every-invitation-of-the-agency" aria-label="Permalink to &quot;Flow A — The Owner views every invitation of the Agency&quot;">​</a></h2><ol><li>Owner → Client: opens the pending-invitation tab in the Member list of the Agency.</li><li>Client → System: requests the invitations of the Agency (<code>GET /api/v1/agencies/{agencyId}/invitations</code>).</li><li>System — list: a. Confirms the caller is the Owner of the Agency — otherwise <code>403 NOT_AGENCY_OWNER</code>. b. Reads every invitation of the Agency, whatever its status, including PENDING ones already past their expiry time. c. Derives expiry as it maps the answer: an invitation that is PENDING but past its expiry time is reported as EXPIRED, without that change being written back to storage.</li><li>System → Client: the invitations with their reported statuses.</li><li>Client: renders the list with the reported statuses — PENDING, EXPIRED, ACCEPTED and REVOKED.</li></ol><h2 id="flow-b-—-the-owner-cancels-an-open-invitation" tabindex="-1">Flow B — The Owner cancels an open invitation <a class="header-anchor" href="#flow-b-—-the-owner-cancels-an-open-invitation" aria-label="Permalink to &quot;Flow B — The Owner cancels an open invitation&quot;">​</a></h2><ol><li>Owner → Client: selects Cancel on an invitation row.</li><li>Client → System: submits the cancellation (<code>DELETE /api/v1/agencies/{agencyId}/invitations/{invitationId}</code>).</li><li>System — cancel: a. Confirms the caller is the Owner of the Agency — otherwise <code>403 NOT_AGENCY_OWNER</code>. b. Finds the invitation by identifier inside that Agency — not found → <code>404 INVITATION_NOT_FOUND</code>. c. Confirms the invitation is still PENDING in storage — anything else → <code>400 INVALID_INVITATION</code>. d. Marks the invitation REVOKED.</li><li>System → Client: no data, the cancellation is done.</li><li>Client: drops the row from the open list, or marks it as withdrawn.</li></ol><h2 id="flow-c-—-the-invitee-views-their-own-open-invitations" tabindex="-1">Flow C — The Invitee views their own open invitations <a class="header-anchor" href="#flow-c-—-the-invitee-views-their-own-open-invitations" aria-label="Permalink to &quot;Flow C — The Invitee views their own open invitations&quot;">​</a></h2><ol><li>Invitee → Client: opens the section listing their own invitations.</li><li>Client → System: requests their invitations (<code>GET /api/v1/agencies/invitations/my-pending</code>).</li><li>System — list: a. Reads the invitations addressed to the email of the signed-in user. b. Drops every invitation that is no longer PENDING or has passed its expiry time. Unlike Flow A, the Invitee sees nothing beyond the invitations that are genuinely still open.</li><li>System → Client: the still-valid invitations.</li><li>Client: renders them, each with an accept action (3.4.7) and a decline action.</li></ol><h2 id="flow-d-—-the-invitee-declines-an-invitation" tabindex="-1">Flow D — The Invitee declines an invitation <a class="header-anchor" href="#flow-d-—-the-invitee-declines-an-invitation" aria-label="Permalink to &quot;Flow D — The Invitee declines an invitation&quot;">​</a></h2><ol><li>Invitee → Client: selects Decline on an invitation.</li><li>Client → System: submits the decline with the token (<code>POST /api/v1/agencies/invitations/decline</code>).</li><li>System: finds the invitation by token and marks it REVOKED. The status model has no separate value for a declined invitation, so it shares the withdrawn state.</li><li>System → Client: no data, the decline is done.</li><li>Client: drops the item from the Invitee&#39;s list.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>Error code</th></tr></thead><tbody><tr><td>List (Owner)</td><td>Caller is not the Owner</td><td>403</td><td><code>NOT_AGENCY_OWNER</code></td></tr><tr><td>Cancel</td><td>Caller is not the Owner</td><td>403</td><td><code>NOT_AGENCY_OWNER</code></td></tr><tr><td>Cancel</td><td>Invitation does not exist or belongs to another Agency</td><td>404</td><td><code>INVITATION_NOT_FOUND</code></td></tr><tr><td>Cancel</td><td>Invitation is no longer PENDING</td><td>400</td><td><code>INVALID_INVITATION</code></td></tr><tr><td>Accept</td><td>Invitation lapsed or already handled at the moment of acceptance</td><td>400</td><td><code>INVALID_INVITATION</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>No divergence from <code>spec.md</code>: expiry is derived when the list is read rather than by a scheduled job, it defaults to 30 days and is settable between 1 and 30 days, and the Invitee&#39;s own list is addressed by their email rather than by a general account route.</li><li>This file details the decline path as a flow of its own, which <code>spec.md</code> describes among the interfaces of the feature. That is added detail, not a correction.</li></ul>',18)])])}const u=t(o,[["render",s]]);export{w as __pageData,u as default};
